/**
 * @fileoverview Tests for id-denylist rule.
 * @author Keith Cirkel
 */

"use strict";

//------------------------------------------------------------------------------
// Requirements
//------------------------------------------------------------------------------

const rule = require("../../../lib/rules/id-denylist"),
	RuleTester = require("../../../lib/rule-tester/rule-tester");

//------------------------------------------------------------------------------
// Tests
//------------------------------------------------------------------------------

const ruleTester = new RuleTester({
	languageOptions: {
		ecmaVersion: 5,
		sourceType: "script",
	},
});
const error = {
	messageId: "restricted",
};

ruleTester.run("id-denylist", rule, {
	valid: [
		{
			code: 'foo = "bar"',
			options: ["bar"],
		},
		{
			code: 'bar = "bar"',
			options: ["foo"],
		},
		{
			code: 'foo = "bar"',
			options: ["f", "fo", "fooo", "bar"],
		},
		{
			code: "function foo(){}",
			options: ["bar"],
		},
		{
			code: "foo()",
			options: ["f", "fo", "fooo", "bar"],
		},
		{
			code: "import { foo as bar } from 'mod'",
			options: ["foo"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
		},
		{
			code: "export { foo as bar } from 'mod'",
			options: ["foo"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
		},
		{
			code: "foo.bar()",
			options: ["f", "fo", "fooo", "b", "ba", "baz"],
		},
		{
			code: "var foo = bar.baz;",
			options: ["f", "fo", "fooo", "b", "ba", "barr", "bazz"],
		},
		{
			code: "var foo = bar.baz.bing;",
			options: ["f", "fo", "fooo", "b", "ba", "barr", "bazz", "bingg"],
		},
		{
			code: "foo.bar.baz = bing.bong.bash;",
			options: ["f", "fo", "fooo", "b", "ba", "barr", "bazz", "bingg"],
		},
		{
			code: "if (foo.bar) {}",
			options: ["f", "fo", "fooo", "b", "ba", "barr", "bazz", "bingg"],
		},
		{
			code: "var obj = { key: foo.bar };",
			options: ["f", "fo", "fooo", "b", "ba", "barr", "bazz", "bingg"],
		},
		{
			code: "const {foo: bar} = baz",
			options: ["foo"],
			languageOptions: { ecmaVersion: 6 },
		},
		{
			code: "const {foo: {bar: baz}} = qux",
			options: ["foo", "bar"],
			languageOptions: { ecmaVersion: 6 },
		},
		{
			code: "function foo({ bar: baz }) {}",
			options: ["bar"],
			languageOptions: { ecmaVersion: 6 },
		},
		{
			code: "function foo({ bar: {baz: qux} }) {}",
			options: ["bar", "baz"],
			languageOptions: { ecmaVersion: 6 },
		},
		{
			code: "function foo({baz} = obj.qux) {}",
			options: ["qux"],
			languageOptions: { ecmaVersion: 6 },
		},
		{
			code: "function foo({ foo: {baz} = obj.qux }) {}",
			options: ["qux"],
			languageOptions: { ecmaVersion: 6 },
		},
		{
			code: "({a: bar = obj.baz});",
			options: ["baz"],
			languageOptions: { ecmaVersion: 6 },
		},
		{
			code: "({foo: {a: bar = obj.baz}} = qux);",
			options: ["baz"],
			languageOptions: { ecmaVersion: 6 },
		},
		{
			code: "var arr = [foo.bar];",
			options: ["f", "fo", "fooo", "b", "ba", "barr", "bazz", "bingg"],
		},
		{
			code: "[foo.bar]",
			options: ["f", "fo", "fooo", "b", "ba", "barr", "bazz", "bingg"],
		},
		{
			code: "[foo.bar.nesting]",
			options: ["f", "fo", "fooo", "b", "ba", "barr", "bazz", "bingg"],
		},
		{
			code: "if (foo.bar === bar.baz) { [foo.bar] }",
			options: ["f", "fo", "fooo", "b", "ba", "barr", "bazz", "bingg"],
		},
		{
			code: "var myArray = new Array(); var myDate = new Date();",
			options: ["array", "date", "mydate", "myarray", "new", "var"],
		},
		{
			code: "foo()",
			options: ["foo"],
		},
		{
			code: "foo.bar()",
			options: ["bar"],
		},
		{
			code: "foo.bar",
			options: ["bar"],
		},
		{
			code: "({foo: obj.bar.bar.bar.baz} = {});",
			options: ["foo", "bar"],
			languageOptions: { ecmaVersion: 6 },
		},
		{
			code: "({[obj.bar]: a = baz} = qux);",
			options: ["bar"],
			languageOptions: { ecmaVersion: 6 },
		},

		// references to global variables
		{
			code: "Number.parseInt()",
			options: ["Number"],
		},
		{
			code: "x = Number.NaN;",
			options: ["Number"],
		},
		{
			code: "var foo = undefined;",
			options: ["undefined"],
		},
		{
			code: "if (foo === undefined);",
			options: ["undefined"],
		},
		{
			code: "obj[undefined] = 5;", // creates obj["undefined"]. It should be disallowed, but the rule doesn't know values of globals and can't control computed access.
			options: ["undefined"],
		},
		{
			code: "foo = { [myGlobal]: 1 };",
			options: ["myGlobal"],
			languageOptions: {
				ecmaVersion: 6,
				globals: { myGlobal: "readonly" },
			},
		},
		{
			code: "({ myGlobal } = foo);", // writability doesn't affect the logic, it's always assumed that user doesn't have control over the names of globals.
			options: ["myGlobal"],
			languageOptions: {
				ecmaVersion: 6,
				globals: { myGlobal: "writable" },
			},
		},
		{
			code: "/* global myGlobal: readonly */ myGlobal = 5;",
			options: ["myGlobal"],
		},
		{
			code: "var foo = [Map];",
			options: ["Map"],
			languageOptions: {
				ecmaVersion: 6,
			},
		},
		{
			code: "var foo = { bar: window.baz };",
			options: ["window"],
			languageOptions: {
				globals: {
					window: "readonly",
				},
			},
		},

		// Class fields
		{
			code: "class C { camelCase; #camelCase; #camelCase2() {} }",
			options: ["foo"],
			languageOptions: { ecmaVersion: 2022 },
		},
		{
			code: "class C { snake_case; #snake_case; #snake_case2() {} }",
			options: ["foo"],
			languageOptions: { ecmaVersion: 2022 },
		},

		// Meta-properties
		{
			code: "import.meta",
			options: ["import", "meta"],
			languageOptions: { ecmaVersion: 2020, sourceType: "module" },
		},
		{
			code: "function foo() { new.target; }",
			options: ["new", "target"],
			languageOptions: { ecmaVersion: 6 },
		},

		// Import attribute keys
		{
			code: "import foo from 'foo.json' with { type: 'json' }",
			options: ["type"],
			languageOptions: { ecmaVersion: 2025, sourceType: "module" },
		},
		{
			code: "export * from 'foo.json' with { type: 'json' }",
			options: ["type"],
			languageOptions: { ecmaVersion: 2025, sourceType: "module" },
		},
		{
			code: "export { default } from 'foo.json' with { type: 'json' }",
			options: ["type"],
			languageOptions: { ecmaVersion: 2025, sourceType: "module" },
		},
		{
			code: "import('foo.json', { with: { type: 'json' } })",
			options: ["with", "type"],
			languageOptions: { ecmaVersion: 2025 },
		},
		{
			code: "import('foo.json', { 'with': { type: 'json' } })",
			options: ["type"],
			languageOptions: { ecmaVersion: 2025 },
		},
		{
			code: "import('foo.json', { with: { type } })",
			options: ["type"],
			languageOptions: { ecmaVersion: 2025 },
		},
	],
	invalid: [
		{
			code: 'foo = "bar"',
			options: ["foo"],
			errors: [error],
		},
		{
			code: 'bar = "bar"',
			options: ["bar"],
			errors: [error],
		},
		{
			code: 'foo = "bar"',
			options: ["f", "fo", "foo", "bar"],
			errors: [error],
		},
		{
			code: "function foo(){}",
			options: ["f", "fo", "foo", "bar"],
			errors: [error],
		},
		{
			code: "import foo from 'mod'",
			options: ["foo"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
			errors: [error],
		},
		{
			code: "import * as foo from 'mod'",
			options: ["foo"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
			errors: [error],
		},
		{
			code: "export * as foo from 'mod'",
			options: ["foo"],
			languageOptions: { ecmaVersion: 2020, sourceType: "module" },
			errors: [error],
		},
		{
			code: "import { foo } from 'mod'",
			options: ["foo"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
			errors: [error],
		},
		{
			code: "import { foo as bar } from 'mod'",
			options: ["bar"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
			errors: [
				{
					messageId: "restricted",
					data: { name: "bar" },
					column: 17,
				},
			],
		},
		{
			code: "import { foo as bar } from 'mod'",
			options: ["foo", "bar"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
			errors: [
				{
					messageId: "restricted",
					data: { name: "bar" },
					column: 17,
				},
			],
		},
		{
			code: "import { foo as foo } from 'mod'",
			options: ["foo"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
			errors: [
				{
					messageId: "restricted",
					data: { name: "foo" },
					column: 17,
				},
			],
		},
		{
			code: "import { foo, foo as bar } from 'mod'",
			options: ["foo"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
			errors: [
				{
					messageId: "restricted",
					data: { name: "foo" },
					column: 10,
				},
			],
		},
		{
			code: "import { foo as bar, foo } from 'mod'",
			options: ["foo"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
			errors: [
				{
					messageId: "restricted",
					data: { name: "foo" },
					column: 22,
				},
			],
		},
		{
			code: "import foo, { foo as bar } from 'mod'",
			options: ["foo"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
			errors: [
				{
					messageId: "restricted",
					data: { name: "foo" },
					column: 8,
				},
			],
		},
		{
			code: "var foo; export { foo as bar };",
			options: ["bar"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
			errors: [
				{
					messageId: "restricted",
					data: { name: "bar" },
					column: 26,
				},
			],
		},
		{
			code: "var foo; export { foo };",
			options: ["foo"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
			errors: [
				{
					messageId: "restricted",
					data: { name: "foo" },
					column: 5,
				},
				{
					messageId: "restricted",
					data: { name: "foo" },
					column: 19,
				},
			],
		},
		{
			code: "var foo; export { foo as bar };",
			options: ["foo"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
			errors: [
				{
					messageId: "restricted",
					data: { name: "foo" },
					column: 5,
				},

				// reports each occurrence of local identifier, although it's renamed in this export specifier
				{
					messageId: "restricted",
					data: { name: "foo" },
					column: 19,
				},
			],
		},
		{
			code: "var foo; export { foo as foo };",
			options: ["foo"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
			errors: [
				{
					messageId: "restricted",
					data: { name: "foo" },
					column: 5,
				},
				{
					messageId: "restricted",
					data: { name: "foo" },
					column: 19,
				},
				{
					messageId: "restricted",
					data: { name: "foo" },
					column: 26,
				},
			],
		},
		{
			code: "var foo; export { foo as bar };",
			options: ["foo", "bar"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
			errors: [
				{
					messageId: "restricted",
					data: { name: "foo" },
					column: 5,
				},
				{
					messageId: "restricted",
					data: { name: "foo" },
					column: 19,
				},
				{
					messageId: "restricted",
					data: { name: "bar" },
					column: 26,
				},
			],
		},
		{
			code: "export { foo } from 'mod'",
			options: ["foo"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
			errors: [error],
		},
		{
			code: "export { foo as bar } from 'mod'",
			options: ["bar"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
			errors: [
				{
					messageId: "restricted",
					data: { name: "bar" },
					column: 17,
				},
			],
		},
		{
			code: "export { foo as bar } from 'mod'",
			options: ["foo", "bar"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
			errors: [
				{
					messageId: "restricted",
					data: { name: "bar" },
					column: 17,
				},
			],
		},
		{
			code: "export { foo as foo } from 'mod'",
			options: ["foo"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
			errors: [
				{
					messageId: "restricted",
					data: { name: "foo" },
					column: 17,
				},
			],
		},
		{
			code: "export { foo, foo as bar } from 'mod'",
			options: ["foo"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
			errors: [
				{
					messageId: "restricted",
					data: { name: "foo" },
					column: 10,
				},
			],
		},
		{
			code: "export { foo as bar, foo } from 'mod'",
			options: ["foo"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
			errors: [
				{
					messageId: "restricted",
					data: { name: "foo" },
					column: 22,
				},
			],
		},
		{
			code: "foo.bar()",
			options: ["f", "fo", "foo", "b", "ba", "baz"],
			errors: [error],
		},
		{
			code: "foo[bar] = baz;",
			options: ["bar"],
			errors: [
				{
					messageId: "restricted",
					data: { name: "bar" },
				},
			],
		},
		{
			code: "baz = foo[bar];",
			options: ["bar"],
			errors: [
				{
					messageId: "restricted",
					data: { name: "bar" },
				},
			],
		},
		{
			code: "var foo = bar.baz;",
			options: ["f", "fo", "foo", "b", "ba", "barr", "bazz"],
			errors: [error],
		},
		{
			code: "var foo = bar.baz;",
			options: ["f", "fo", "fooo", "b", "ba", "bar", "bazz"],
			errors: [error],
		},
		{
			code: "if (foo.bar) {}",
			options: ["f", "fo", "foo", "b", "ba", "barr", "bazz", "bingg"],
			errors: [error],
		},
		{
			code: "var obj = { key: foo.bar };",
			options: ["obj"],
			errors: [error],
		},
		{
			code: "var obj = { key: foo.bar };",
			options: ["key"],
			errors: [error],
		},
		{
			code: "var obj = { key: foo.bar };",
			options: ["foo"],
			errors: [error],
		},
		{
			code: "var arr = [foo.bar];",
			options: ["arr"],
			errors: [error],
		},
